    var prRef = provider.findPr(issue.number, branchPrefix);
    var pr = prRef && prRef.state === 'OPEN' ? provider.prStatus(prRef.number) : prRef;
    return {
        prRef: prRef,
        pr: pr,
        state: {
            issue: issue,
