    }), {});

    test('a MERGED PR plans the sweep BEFORE the close (the sweep rides the close tick)', function () {
        var acts = agent.decideActions(
            { issue: { number: 1410, labels: [] }, pr: { number: 555, state: 'MERGED' },
                activeRunForIssue: false }, {});
        assert.equal(acts.length, 2, 'sweep + close');
        assert.equal(acts[0].type, 'mergedThreadSweep');
        assert.equal(acts[0].prNumber, 555);
        assert.equal(acts[1].type, 'closeIssue', 'the Fixes-#N safety net still fires after the sweep');
    });

    test('the executor delegates to the sweep module (provider + cfg)', function () {
        var calls = { threadReads: [], commentReads: [], commentsPosted: [], resolves: [], replies: [] };
        var provider = pr1410Provider(calls);
        agent.executeAction(provider, { type: 'mergedThreadSweep', prNumber: 1410 },
            { number: 999 }, cfgOf());
        assert.equal(calls.threadReads.length, 1);
        assert.equal(calls.commentsPosted.length, 1);
    });

    test('dry-run plans, never executes (the close path stays untouched in dry runs)', function () {
        var calls = { threadReads: [], commentReads: [], commentsPosted: [], resolves: [], replies: [] };
        var provider = pr1410Provider(calls);
        var outcome = agent.applyIssueAction(provider, { number: 999 },
            { dryRun: true, machineLogins: [BOT] }, { type: 'mergedThreadSweep', prNumber: 1410 });
        assert.equal(outcome, 'planned');
        assert.equal(calls.threadReads.length, 0);
    });
});

