function isMachineNoticeBody(body) {
    var s = stripLeadingHeading(body);
    if (!s) return false;
    // Hidden `<!-- dmtools:... -->` audit markers (naked-pr-rearm, rework-lap,
    // rework-consume, review-verdict, ...) are machine-only bookkeeping —
